#include <iostream>
#include <iomanip>
#include <cstddef>

class MiniArray {
    friend std::ostream& operator<<(std::ostream& output, const MiniArray& a);
    friend std::istream& operator>>(std::istream& input, MiniArray& a);

private:
    size_t size;
    int* ptr;

public:
    explicit MiniArray(size_t s = 4) : size(s), ptr(new int[s]{}) {}
    ~MiniArray() { delete[] ptr; }
};

std::ostream& operator<<(std::ostream& output, const MiniArray& a) {
    for (size_t i = 0; i < a.size; ++i) {
        output << std::setw(6) << a.ptr[i];
        if ((i + 1) % 4 == 0) {
            output << '\n';
        }
    }
    if (a.size % 4 != 0) {
        output << '\n';
    }
    return output; // Cho phep cascaded output
}

std::istream& operator>>(std::istream& input, MiniArray& a) {
    for (size_t i = 0; i < a.size; ++i) {
        input >> a.ptr[i];
    }
    return input; // Cho phep cascaded input
}

int main() {
    MiniArray arr(4);
    if (std::cin >> arr) {
        std::cout << arr;
    }
    return 0;
}

#include <iostream>
#include <cstddef>

class IntArray {
private:
    size_t size;
    int* ptr;

public:
    // Default constructor
    explicit IntArray(size_t s = 3) : size(s), ptr(new int[s]{}) {}

    // Copy constructor (Deep Copy)
    IntArray(const IntArray& orig) : size(orig.size), ptr(new int[orig.size]) {
        for (size_t i = 0; i < size; ++i) {
            ptr[i] = orig.ptr[i];
        }
    }

    // Destructor
    ~IntArray() {
        delete[] ptr;
    }

    void set(size_t index, int val) {
        if (index < size) ptr[index] = val;
    }

    int get(size_t index) const {
        return (index < size) ? ptr[index] : 0;
    }

    size_t getSize() const { return size; }
};

int main() {
    IntArray original(3);
    original.set(0, 100);
    original.set(1, 200);
    original.set(2, 300);

    // Goi copy constructor
    IntArray cloned = original;
    cloned.set(0, 999); // Thay doi tren cloned khong anh huong original

    std::cout << "Original[0]: " << original.get(0) << "\n";
    std::cout << "Cloned[0]: " << cloned.get(0) << "\n";
    return 0;
}

#include <iostream>
#include <stdexcept>
#include <cstddef>

class SafeArray {
private:
    size_t size;
    int* ptr;

public:
    explicit SafeArray(size_t s = 3) : size(s), ptr(new int[s]{}) {}
    ~SafeArray() { delete[] ptr; }

    SafeArray(const SafeArray& other) : size(other.size), ptr(new int[other.size]) {
        for (size_t i = 0; i < size; ++i) ptr[i] = other.ptr[i];
    }

    // Toan tu gan voi kiem tra tu gan (self-assignment check)
    SafeArray& operator=(const SafeArray& right) {
        if (&right != this) {
            if (size != right.size) {
                delete[] ptr;
                size = right.size;
                ptr = new int[size];
            }
            for (size_t i = 0; i < size; ++i) {
                ptr[i] = right.ptr[i];
            }
        }
        return *this;
    }

    // Toan tu so sanh == va !=
    bool operator==(const SafeArray& right) const {
        if (size != right.size) return false;
        for (size_t i = 0; i < size; ++i) {
            if (ptr[i] != right.ptr[i]) return false;
        }
        return true;
    }

    bool operator!=(const SafeArray& right) const {
        return !(*this == right);
    }

    // Toan tu [] cho doi tuong non-const (tra ve lvalue reference)
    int& operator[](size_t index) {
        if (index >= size) throw std::out_of_range("Index out of range");
        return ptr[index];
    }

    // Toan tu [] cho doi tuong const (read-only)
    int operator[](size_t index) const {
        if (index >= size) throw std::out_of_range("Index out of range");
        return ptr[index];
    }

    size_t getSize() const { return size; }
};

int main() {
    SafeArray a(2);
    a[0] = 10; // Su dung non-const operator[]
    a[1] = 20;

    SafeArray b = a; // Copy constructor
    std::cout << "Equal: " << (a == b ? "true" : "false") << '\n';

    b[0] = 99;
    std::cout << "Not Equal: " << (a != b ? "true" : "false") << '\n';

    // Kiem tra self-assignment
    a = a;
    std::cout << "a[0] after self-assign: " << a[0] << '\n';

    return 0;
}
